import pandas as pd
import numpy as np
import json

# Load data
df = pd.read_csv('/app/benchmark/data.csv')
df['Date'] = pd.to_datetime(df['Date'])
df = df.sort_values('Date').reset_index(drop=True)
df['Year'] = df['Date'].dt.year
df['Month'] = df['Date'].dt.month
df['Decade'] = (df['Year'] // 10) * 10

# Basic stats
price = df['Crude_Oil_Price']
min_price = price.min()
max_price = price.max()
min_date = df.loc[price.idxmin(), 'Date']
max_date = df.loc[price.idxmax(), 'Date']
overall_range = max_price - min_price
mean_price = price.mean()
median_price = price.median()
std_price = price.std()
p25 = price.quantile(0.25)
p75 = price.quantile(0.75)
p10 = price.quantile(0.10)
p90 = price.quantile(0.90)

# CAGR
first_price = df.iloc[0]['Crude_Oil_Price']
last_price = df.iloc[-1]['Crude_Oil_Price']
first_date = df.iloc[0]['Date']
last_date = df.iloc[-1]['Date']
years_span = (last_date - first_date).days / 365.25
cagr = (last_price / first_price) ** (1 / years_span) - 1

# Month-over-month changes
df['MoM_Change'] = price.diff()
df['MoM_Pct'] = price.pct_change() * 100

max_mom_abs_idx = df['MoM_Change'].abs().idxmax()
max_mom_abs = df.loc[max_mom_abs_idx, 'MoM_Change']
max_mom_abs_date = df.loc[max_mom_abs_idx, 'Date']
max_mom_abs_price = df.loc[max_mom_abs_idx, 'Crude_Oil_Price']

max_mom_pct_idx = df['MoM_Pct'].abs().idxmax()
max_mom_pct = df.loc[max_mom_pct_idx, 'MoM_Pct']
max_mom_pct_date = df.loc[max_mom_pct_idx, 'Date']

# Top 10 largest MoM changes (absolute)
top_mom = df.dropna(subset=['MoM_Change']).copy()
top_mom['Abs_MoM'] = top_mom['MoM_Change'].abs()
top10_mom = top_mom.nlargest(10, 'Abs_MoM')[['Date','Crude_Oil_Price','MoM_Change','MoM_Pct']].copy()

# Year-over-year
yearly = df.groupby('Year')['Crude_Oil_Price'].mean().reset_index()
yearly.columns = ['Year', 'Avg_Price']
yearly['YoY_Change'] = yearly['Avg_Price'].diff()
yearly['YoY_Pct'] = yearly['Avg_Price'].pct_change() * 100

# Decade analysis
decade_stats = df.groupby('Decade')['Crude_Oil_Price'].agg(['mean','std','min','max','count']).reset_index()
decade_stats.columns = ['Decade','Mean','Std','Min','Max','Count']
highest_decade = decade_stats.loc[decade_stats['Mean'].idxmax()]

# Rolling volatility (12-month)
df['Rolling_Std_12'] = price.rolling(12).std()

# Key events mapping
events = [
    {"date": "1973-10-01", "label": "OPEC Embargo", "y_offset": 20},
    {"date": "1979-05-01", "label": "Iranian Revolution", "y_offset": 15},
    {"date": "1986-04-01", "label": "1986 Oil Crash", "y_offset": -15},
    {"date": "1990-08-01", "label": "Gulf War", "y_offset": 15},
    {"date": "1998-12-01", "label": "Asian Crisis Low", "y_offset": -15},
    {"date": "2008-07-01", "label": "2008 Peak", "y_offset": 15},
    {"date": "2008-12-01", "label": "Financial Crisis", "y_offset": -20},
    {"date": "2014-11-01", "label": "OPEC Price War", "y_offset": -15},
    {"date": "2020-04-01", "label": "COVID-19 Crash", "y_offset": -15},
    {"date": "2022-03-01", "label": "Ukraine Conflict", "y_offset": 15},
]

# Prepare chart data
dates_str = df['Date'].dt.strftime('%Y-%m').tolist()
prices_list = df['Crude_Oil_Price'].round(2).tolist()
rolling_std = df['Rolling_Std_12'].round(2).tolist()
mom_changes = df['MoM_Pct'].round(2).fillna(0).tolist()

yearly_labels = yearly['Year'].tolist()
yearly_prices = yearly['Avg_Price'].round(2).tolist()
yearly_yoy = yearly['YoY_Pct'].round(2).fillna(0).tolist()

decade_labels = [f"{int(d)}s" for d in decade_stats['Decade'].tolist()]
decade_means = decade_stats['Mean'].round(2).tolist()
decade_stds = decade_stats['Std'].round(2).tolist()
decade_mins = decade_stats['Min'].round(2).tolist()
decade_maxs = decade_stats['Max'].round(2).tolist()

# Price distribution histogram
hist_counts, hist_edges = np.histogram(price, bins=30)
hist_labels = [f"${e:.0f}" for e in hist_edges[:-1]]
hist_values = hist_counts.tolist()

# Build HTML
html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Global Crude Oil Price Trends: A Historical Analysis (1970–2026)</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.1/dist/chart.umd.min.js"></script>
<script src="https://cdn.jsdelivr.net/npm/chartjs-plugin-annotation@3.0.1/dist/chartjs-plugin-annotation.min.js"></script>
<style>
  :root {{
    --bg: #0f1117;
    --surface: #1a1d27;
    --surface2: #242734;
    --border: #2e3242;
    --text: #e4e6f0;
    --text-dim: #8b8fa3;
    --accent: #4f8ff7;
    --accent2: #f59e0b;
    --red: #ef4444;
    --green: #22c55e;
    --orange: #f97316;
  }}
  * {{ margin: 0; padding: 0; box-sizing: border-box; }}
  body {{
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    background: var(--bg);
    color: var(--text);
    line-height: 1.6;
    padding: 0;
  }}
  .header {{
    background: linear-gradient(135deg, #1a1d27 0%, #242734 100%);
    border-bottom: 1px solid var(--border);
    padding: 48px 0 40px;
    text-align: center;
  }}
  .header h1 {{
    font-size: 2.2rem;
    font-weight: 700;
    letter-spacing: -0.02em;
    margin-bottom: 8px;
  }}
  .header .subtitle {{
    color: var(--text-dim);
    font-size: 1.05rem;
    max-width: 700px;
    margin: 0 auto;
  }}
  .container {{ max-width: 1200px; margin: 0 auto; padding: 0 32px; }}
  .kpi-grid {{
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
    gap: 16px;
    margin: 32px 0;
  }}
  .kpi-card {{
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 20px;
  }}
  .kpi-card .label {{ font-size: 0.8rem; color: var(--text-dim); text-transform: uppercase; letter-spacing: 0.05em; margin-bottom: 6px; }}
  .kpi-card .value {{ font-size: 1.75rem; font-weight: 700; }}
  .kpi-card .detail {{ font-size: 0.82rem; color: var(--text-dim); margin-top: 4px; }}
  .section {{
    margin: 48px 0;
  }}
  .section h2 {{
    font-size: 1.5rem;
    font-weight: 600;
    margin-bottom: 8px;
    padding-bottom: 12px;
    border-bottom: 2px solid var(--accent);
    display: inline-block;
  }}
  .section .desc {{
    color: var(--text-dim);
    margin-bottom: 24px;
    max-width: 800px;
  }}
  .chart-container {{
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 24px;
    margin: 20px 0;
    position: relative;
  }}
  .chart-container canvas {{ max-height: 420px; }}
  .chart-title {{
    font-size: 1rem;
    font-weight: 600;
    margin-bottom: 16px;
  }}
  table {{
    width: 100%;
    border-collapse: collapse;
    font-size: 0.9rem;
  }}
  th, td {{
    padding: 10px 14px;
    text-align: left;
    border-bottom: 1px solid var(--border);
  }}
  th {{
    background: var(--surface2);
    color: var(--text-dim);
    font-weight: 600;
    text-transform: uppercase;
    font-size: 0.75rem;
    letter-spacing: 0.05em;
  }}
  td {{ color: var(--text); }}
  tr:hover td {{ background: var(--surface2); }}
  .table-wrap {{
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 12px;
    overflow: hidden;
    margin: 20px 0;
  }}
  .positive {{ color: var(--green); }}
  .negative {{ color: var(--red); }}
  .two-col {{ display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }}
  @media (max-width: 768px) {{ .two-col {{ grid-template-columns: 1fr; }} }}
  .stat-row {{ display: flex; justify-content: space-between; padding: 10px 0; border-bottom: 1px solid var(--border); }}
  .stat-row:last-child {{ border-bottom: none; }}
  .stat-label {{ color: var(--text-dim); }}
  .stat-value {{ font-weight: 600; }}
  .insight-box {{
    background: rgba(79, 143, 247, 0.08);
    border-left: 3px solid var(--accent);
    padding: 16px 20px;
    border-radius: 0 8px 8px 0;
    margin: 16px 0;
    font-size: 0.92rem;
  }}
  .footer {{
    text-align: center;
    padding: 40px 0;
    color: var(--text-dim);
    font-size: 0.82rem;
    border-top: 1px solid var(--border);
    margin-top: 60px;
  }}
</style>
</head>
<body>

<div class="header">
  <div class="container">
    <h1>Global Crude Oil Price Trends</h1>
    <p class="subtitle">A Historical Analysis of Monthly Crude Oil Prices (1970–2026) — {len(df)} observations across {years_span:.1f} years</p>
  </div>
</div>

<div class="container">

<!-- EXECUTIVE OVERVIEW -->
<div class="section">
  <h2>Executive Overview</h2>
  <p class="desc">This report analyzes {len(df)} monthly crude oil price observations from {first_date.strftime('%B %Y')} to {last_date.strftime('%B %Y')}, spanning {years_span:.1f} years of global energy market history.</p>

  <div class="kpi-grid">
    <div class="kpi-card">
      <div class="label">Overall Price Range</div>
      <div class="value">${overall_range:.2f}</div>
      <div class="detail">${min_price:.2f} – ${max_price:.2f} per barrel</div>
    </div>
    <div class="kpi-card">
      <div class="label">CAGR (1970–2026)</div>
      <div class="value">{cagr*100:.2f}%</div>
      <div class="detail">${first_price:.2f} → ${last_price:.2f}</div>
    </div>
    <div class="kpi-card">
      <div class="label">Max Monthly Change</div>
      <div class="value">{"+" if max_mom_abs > 0 else ""}${max_mom_abs:.2f}</div>
      <div class="detail">{max_mom_abs_date.strftime('%b %Y')} ({max_mom_pct:.1f}% in {max_mom_pct_date.strftime('%b %Y')})</div>
    </div>
    <div class="kpi-card">
      <div class="label">Highest Avg. Decade</div>
      <div class="value">{int(highest_decade['Decade'])}s</div>
      <div class="detail">${highest_decade['Mean']:.2f}/bbl average</div>
    </div>
    <div class="kpi-card">
      <div class="label">Price Volatility (σ)</div>
      <div class="value">${std_price:.2f}</div>
      <div class="detail">Overall standard deviation</div>
    </div>
  </div>

  <div class="insight-box">
    Crude oil prices have risen from ${first_price:.2f}/bbl in {first_date.strftime('%B %Y')} to ${last_price:.2f}/bbl in {last_date.strftime('%B %Y')}, achieving a compound annual growth rate of {cagr*100:.2f}%. The all-time high of ${max_price:.2f} was recorded in {max_date.strftime('%B %Y')}, while the minimum of ${min_price:.2f} occurred in {min_date.strftime('%B %Y')}. The dataset reveals multiple structural regime changes driven by geopolitical crises, demand shocks, and shifts in production dynamics.
  </div>
</div>

<!-- LONG-TERM TREND -->
<div class="section">
  <h2>Long-Term Price Trajectory (1970–2026)</h2>
  <p class="desc">The full monthly time series reveals distinct pricing eras: the pre-embargo low-price era, the volatile 1970s–80s driven by OPEC politics, a relatively subdued 1990s, the commodity supercycle of the 2000s, and the post-shale era of heightened volatility.</p>

  <div class="chart-container">
    <div class="chart-title">Monthly Crude Oil Price (USD/barrel), 1970–2026</div>
    <canvas id="mainChart" height="180"></canvas>
  </div>

  <div class="chart-container">
    <div class="chart-title">Annual Average Price with Year-over-Year Change (%)</div>
    <canvas id="yearlyChart" height="160"></canvas>
  </div>

  <div class="insight-box">
    The time series shows a clear long-term upward trend punctuated by sharp discontinuities. The most dramatic absolute price increase occurred during 2007–2008, when prices surged past $130/bbl before collapsing nearly 70% in five months during the Global Financial Crisis.
  </div>
</div>

<!-- DECADE BY DECADE -->
<div class="section">
  <h2>Decade-by-Decade Breakdown</h2>
  <p class="desc">Comparing pricing dynamics across decades reveals how the global oil market has structurally evolved in terms of price level, volatility, and dominant drivers.</p>

  <div class="chart-container">
    <div class="chart-title">Average Price & Volatility by Decade</div>
    <canvas id="decadeChart" height="140"></canvas>
  </div>

  <div class="table-wrap">
    <table>
      <thead>
        <tr><th>Decade</th><th>Mean ($/bbl)</th><th>Std Dev</th><th>Min</th><th>Max</th><th>Observations</th><th>Key Driver</th></tr>
      </thead>
      <tbody>
"""

decade_events = {{
    1970: "OPEC embargoes & Iranian Revolution",
    1980: "Post-revolution spike, then glut & crash",
    1990: "Post-Gulf War normalization, Asian crisis",
    2000: "China-led demand supercycle, GFC crash",
    2010: "Shale revolution, OPEC price wars",
    2020: "COVID-19 crash, Ukraine conflict, energy transition"
}}

for _, row in decade_stats.iterrows():
    d = int(row['Decade'])
    html += f"""        <tr>
          <td><strong>{d}s</strong></td>
          <td>${row['Mean']:.2f}</td>
          <td>${row['Std']:.2f}</td>
          <td>${row['Min']:.2f}</td>
          <td>${row['Max']:.2f}</td>
          <td>{int(row['Count'])}</td>
          <td>{decade_events.get(d, "—")}</td>
        </tr>
"""

html += """      </tbody>
    </table>
  </div>
"""

# Decade narratives
decade_narratives = {
    1970: f"The 1970s began with oil at just ${df[df['Year']==1970].iloc[0]['Crude_Oil_Price']:.2f}/bbl and ended above $39. The OPEC embargo of October 1973 triggered the first major price shock, with prices jumping from $2.70 to $13.00 in a single quarter — a ~380% increase. The Iranian Revolution in 1979 drove a second shock, pushing prices past $40 for the first time.",
    1980: f"Prices peaked at ~$40 in early 1980 before a long decline driven by demand destruction, non-OPEC supply growth, and Saudi Arabia's decision to defend market share. The 1986 crash saw prices fall from ~$27 to under $10 in mid-1986 — a collapse of over 60% in six months.",
    1990: f"The 1990s were the most stable decade, with prices oscillating between $10 and $35. Iraq's invasion of Kuwait (August 1990) caused a short-lived spike. The Asian Financial Crisis in 1997–98 pushed prices to decade lows near $10/bbl, before a recovery in 1999.",
    2000: f"The 2000s saw the most dramatic price trajectory in the dataset. Driven by surging Chinese demand and constrained supply, prices rose from ~$25 in 2000 to an all-time peak of ${max_price:.2f} in {max_date.strftime('%B %Y')}. The subsequent crash during the Global Financial Crisis brought prices down to ~$41 by December 2008.",
    2010: f"The 2010s were defined by the U.S. shale revolution. Prices remained above $90 through mid-2014 before OPEC's decision not to cut production triggered a crash to under $30 by early 2016. Prices partially recovered but never sustained above $80 for long.",
    2020: f"The 2020s began with the COVID-19 demand shock that sent prices to ${df[(df['Year']==2020)&(df['Month']==4)].iloc[0]['Crude_Oil_Price']:.2f} in April 2020. The recovery was swift, amplified by Russia's invasion of Ukraine in 2022 which pushed prices back above $110. By early 2026, prices have settled in the $60–88 range."
}

for d, narrative in decade_narratives.items():
    label = f"{d}s"
    html += f"""  <div class="insight-box"><strong>{label}:</strong> {narrative}</div>
"""

html += """</div>

<!-- VOLATILITY AND SHOCKS -->
<div class="section">
  <h2>Price Volatility & Major Shocks</h2>
  <p class="desc">Volatility analysis reveals clustering of extreme price moves around geopolitical crises, financial contagion events, and supply-demand shocks.</p>

  <div class="chart-container">
    <div class="chart-title">12-Month Rolling Standard Deviation (USD/barrel)</div>
    <canvas id="volChart" height="140"></canvas>
  </div>

  <div class="chart-container">
    <div class="chart-title">Month-over-Month Price Change (%)</div>
    <canvas id="momChart" height="140"></canvas>
  </div>

  <div class="table-wrap">
    <table>
      <thead>
        <tr><th>Date</th><th>Price ($/bbl)</th><th>MoM Change ($)</th><th>MoM Change (%)</th></tr>
      </thead>
      <tbody>
"""

for _, row in top10_mom.iterrows():
    cls = "positive" if row['MoM_Change'] > 0 else "negative"
    sign = "+" if row['MoM_Change'] > 0 else ""
    html += f"""        <tr>
          <td>{row['Date'].strftime('%b %Y')}</td>
          <td>${row['Crude_Oil_Price']:.2f}</td>
          <td class="{cls}">{sign}${row['MoM_Change']:.2f}</td>
          <td class="{cls}">{sign}{row['MoM_Pct']:.1f}%</td>
        </tr>
"""

html += f"""      </tbody>
    </table>
