import pandas as pd
import numpy as np
import json

# Load data
df = pd.read_csv('/app/benchmark/data.csv')
df['Date'] = pd.to_datetime(df['Date'])
df = df.sort_values('Date').reset_index(drop=True)
df['Year'] = df['Date'].dt.year
df['Month'] = df['Date'].dt.month
df['Decade'] = (df['Year'] // 10) * 10

# Basic stats
price = df['Crude_Oil_Price']
min_price = price.min()
max_price = price.max()
min_date = df.loc[price.idxmin(), 'Date']
max_date = df.loc[price.idxmax(), 'Date']
overall_range = max_price - min_price
mean_price = price.mean()
median_price = price.median()
std_price = price.std()
p25 = price.quantile(0.25)
p75 = price.quantile(0.75)
p10 = price.quantile(0.10)
p90 = price.quantile(0.90)

# CAGR
first_price = df.iloc[0]['Crude_Oil_Price']
last_price = df.iloc[-1]['Crude_Oil_Price']
first_date = df.iloc[0]['Date']
last_date = df.iloc[-1]['Date']
years_span = (last_date - first_date).days / 365.25
cagr = (last_price / first_price) ** (1 / years_span) - 1

# Month-over-month changes
df['MoM_Change'] = price.diff()
df['MoM_Pct'] = price.pct_change() * 100

max_mom_abs_idx = df['MoM_Change'].abs().idxmax()
max_mom_abs = df.loc[max_mom_abs_idx, 'MoM_Change']
max_mom_abs_date = df.loc[max_mom_abs_idx, 'Date']
max_mom_abs_price = df.loc[max_mom_abs_idx, 'Crude_Oil_Price']

max_mom_pct_idx = df['MoM_Pct'].abs().idxmax()
max_mom_pct = df.loc[max_mom_pct_idx, 'MoM_Pct']
max_mom_pct_date = df.loc[max_mom_pct_idx, 'Date']

# Top 10 largest MoM changes (absolute)
top_mom = df.dropna(subset=['MoM_Change']).copy()
top_mom['Abs_MoM'] = top_mom['MoM_Change'].abs()
top10_mom = top_mom.nlargest(10, 'Abs_MoM')[['Date','Crude_Oil_Price','MoM_Change','MoM_Pct']].copy()

# Year-over-year
yearly = df.groupby('Year')['Crude_Oil_Price'].mean().reset_index()
yearly.columns = ['Year', 'Avg_Price']
yearly['YoY_Change'] = yearly['Avg_Price'].diff()
yearly['YoY_Pct'] = yearly['Avg_Price'].pct_change() * 100

# Decade analysis
decade_stats = df.groupby('Decade')['Crude_Oil_Price'].agg(['mean','std','min','max','count']).reset_index()
decade_stats.columns = ['Decade','Mean','Std','Min','Max','Count']
highest_decade = decade_stats.loc[decade_stats['Mean'].idxmax()]

# Rolling volatility (12-month)
df['Rolling_Std_12'] = price.rolling(12).std()

# Key events mapping
events = [
    {"date": "1973-10-01", "label": "OPEC Embargo", "y_offset": 20},
    {"date": "1979-05-01", "label": "Iranian Revolution", "y_offset": 15},
    {"date": "1986-04-01", "label": "1986 Oil Crash", "y_offset": -15},
    {"date": "1990-08-01", "label": "Gulf War", "y_offset": 15},
    {"date": "1998-12-01", "label": "Asian Crisis Low", "y_offset": -15},
    {"date": "2008-07-01", "label": "2008 Peak", "y_offset": 15},
    {"date": "2008-12-01", "label": "Financial Crisis", "y_offset": -20},
    {"date": "2014-11-01", "label": "OPEC Price War", "y_offset": -15},
    {"date": "2020-04-01", "label": "COVID-19 Crash", "y_offset": -15},
    {"date": "2022-03-01", "label": "Ukraine Conflict", "y_offset": 15},
]

# Prepare chart data
dates_str = df['Date'].dt.strftime('%Y-%m').tolist()
prices_list = df['Crude_Oil_Price'].round(2).tolist()
rolling_std = df['Rolling_Std_12'].round(2).tolist()
mom_changes = df['MoM_Pct'].round(2).fillna(0).tolist()

yearly_labels = yearly['Year'].tolist()
yearly_prices = yearly['Avg_Price'].round(2).tolist()
yearly_yoy = yearly['YoY_Pct'].round(2).fillna(0).tolist()

decade_labels = [f"{int(d)}s" for d in decade_stats['Decade'].tolist()]
decade_means = decade_stats['Mean'].round(2).tolist()
decade_stds = decade_stats['Std'].round(2).tolist()
decade_mins = decade_stats['Min'].round(2).tolist()
decade_maxs = decade_stats['Max'].round(2).tolist()

# Price distribution histogram
hist_counts, hist_edges = np.histogram(price, bins=30)
hist_labels = [f"${e:.0f}" for e in hist_edges[:-1]]
hist_values = hist_counts.tolist()

# Build HTML
