</div>

<div class="container">

<!-- EXECUTIVE OVERVIEW -->
<div class="section">
  <h2>Executive Overview</h2>
  <p class="desc">This report analyzes {len(df)} monthly crude oil price observations from {first_date.strftime('%B %Y')} to {last_date.strftime('%B %Y')}, spanning {years_span:.1f} years of global energy market history.</p>

  <div class="kpi-grid">
