      <div class="detail">${first_price:.2f} → ${last_price:.2f}</div>
    </div>
    <div class="kpi-card">
      <div class="label">Max Monthly Change</div>
      <div class="value">{"+" if max_mom_abs > 0 else ""}${max_mom_abs:.2f}</div>
